@Component(FuncionControl.Nombres.FIN_DE_DIA)
@RequiredArgsConstructor
public class FinDeDiaOperacion implements OperacionControl {    // 000330-ENVIA-98

    private final RegistroContableClientFactory registro;       // S151L002R{sistema} / CARGAMOV1
    private final P610Properties props;

    @Override
    public void ejecuta(SolicitudControl s) {
        var cliente = registro.para(s.sistema());               // DAME_TIT con fallback "(S151)S151/OBJECT/L002/REGISTRA ON CMEMP"
        boolean seisDigitos = props.sistemasFecha6Digitos().contains(s.sistema());
        var aviso = seisDigitos
                ? AvisoMovimiento.seisDigitos(98, s.sistema(), s.fecha6())        // FECMOV = FECCONT = FECVAL
                : AvisoMovimiento.ochoDigitos(98, s.sistema(), s.numReg());
        int resultado = cliente.cargaMovimiento(aviso);
        if (resultado != 0) {
            log.warn("CARGAMOV1 función 98 sistema {} resultado {}", s.sistema(), resultado);  // el fuente lo ignora
        }
    }
}

@Component(FuncionControl.Nombres.STABDSAL)
public class GrabaStabdsalOperacion implements OperacionControl {    // 000340-GRABA-STABDSAL
    private static final Set<Long> PERMITIDOS = Set.of(1L, 3L, 5L, 99L);

    @Override
    public void ejecuta(SolicitudControl s) {
        if (!PERMITIDOS.contains(s.numReg())) {
            log.warn("STABDSAL {} no permitido para sistema {}; se ignora", s.numReg(), s.sistema());
            return;                                             // el fuente no deja rastro
        }
        b03.actualizaStabdsal(s.sistema(), (int) s.numReg());  // CONSISMEN F09
    }
}

@Component(FuncionControl.Nombres.ACTUALIZA_B04)
public class ActualizaB04Operacion implements OperacionControl {     // 000350-ACTB04-SISTEMA
    @Override
    @Transactional
    public void ejecuta(SolicitudControl s) {
        if (s.numReg() <= 1 || s.numReg() >= 5) {               // solo 2, 3 o 4
            log.warn("ESTATUS {} fuera de rango para B04; se ignora", s.numReg());
            return;
        }
        b04.findBySistemaAndProductoAndInstrumento(s.sistema(), 0, 0)    // B04SISTEM F1
           .ifPresent(r -> { r.setEstatus((int) s.numReg()); b04.save(r); });   // MANTB04SISTEM F37
    }
}

@Component(FuncionControl.Nombres.CREA_E01)
@RequiredArgsConstructor
public class CreaArchivoE01Operacion implements OperacionControl {   // 000360-CREA-ARCH804

    private final P610Properties props;    // e01-titulo: "(S151)S{sistema}/FILE/E01/10/S151/{fecha}."

    @Override
    public void ejecuta(SolicitudControl s) throws IOException {
        Path destino = props.rutaE01(s.sistema(), s.numReg());
        try (var out = new FixedLengthWriter(destino, 720)) {          // REG-C402 PIC X(720)
            out.write(E01Header.de(s.sistema(), s.numReg()));
            out.write(E01Trailer.de(0, 0, BigDecimal.ZERO.setScale(2)));  // TOTREG, TOTCLAVES, TOTIMPORTE
        }                                                               // CLOSE ... WITH SAVE
    }
}

@Component(FuncionControl.Nombres.CONTROL_CORP)
@RequiredArgsConstructor
public class ControlCorporativoOperacion implements OperacionControl {   // 0000100-ACT-CONT-CORP

    private final ControlCorpRepository control;    // (S151)S151/FILE/CONTROL/CORP.

    @Override
    @Transactional
    public void ejecuta(SolicitudControl s) {
        var hdr = control.header();
        log.info("FECHA ACTUAL: {}", hdr.fechaProceso());
        hdr.setFechaProceso(s.numReg());                                   // la nueva fecha se fija primero
        log.info("FECHA NUEVA: {}", hdr.fechaProceso());

        for (var det : control.detallesHastaCentinela(999)) {             // WKS-DET-SIST = 999 termina
            log.info("SISTEMA: {}", det.sistema());
            if (det.fechaProceso() == hdr.fechaProceso()) {
                log.info("SE EJECUTO CORRECTAMENTE");
            } else {
                log.info("NO HA SIDO PROCESADO DESDE: {}", det.fechaProceso());
            }
            det.setFechaProceso(s.numReg());                               // se regraba siempre
        }
    }   // REWRITE ... INVALID KEY -> excepción y rollback (SET MYSELF(STATUS) TO -1)
}

