@Component(FuncionControl.Nombres.GENERA_ICA)
@RequiredArgsConstructor
public class ArchivoIcaOperacion implements OperacionControl {
    private final IcaProperties ica;

    @Override
    public void ejecuta(SolicitudControl s) throws IOException {
        String f6 = s.fecha6();                                   // AAMMDD
        LocalTime hora = LocalTime.now();                         // ACCEPT WKS-HR-AR FROM TIME
        try (var out = TandemWriter.crea(ica.ruta(f6))) {         // S151/FILE/TANDEM/{fecha6}.
            out.registroNombre(ica.destinoXfer().replace("{fecha6}", f6) + ".");
            out.header(ica, f6, hora, 1);
            out.detalle(ica.detalle(), f6, hora);
            out.trailer(1);
        }
    }
}
